import lzma, re
data = lzma.open('Packages.xz','rt',encoding='utf-8',errors='replace').read()
stanzas = data.split('\n\n')
want = {'binutils-mingw-w64-x86-64','gcc-mingw-w64-x86-64','gcc-mingw-w64-base','gcc-mingw-w64-x86-64-posix','gcc-mingw-w64-x86-64-win32','mingw-w64-common','mingw-w64-x86-64-dev','mingw-w64-x86-64-posix','mingw-w64-x86-64-win32','binutils-mingw-w64'}
idx={}
for s in stanzas:
    if not s.strip(): continue
    fields={}
    key=None
    for line in s.split('\n'):
        if line[:1] in (' ','\t'):
            fields[key]+='\n'+line
        else:
            k,_,v=line.partition(': ')
            fields[k]=v; key=k
    p=fields.get('Package')
    if p in want:
        idx[p]=fields
for p in sorted(want):
    if p in idx:
        print('==',p,idx[p].get('Version'))
        print('  Depends:',idx[p].get('Depends'))
        print('  Filename:',idx[p].get('Filename'))
    else:
        print('==',p,'NOT FOUND')
PY

